            "type": "number"
          },
          "additionalCharges": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "description"
              ],
              "properties": {
                "description": {
                  "type": "string"
                },
                "amount": {
                  "type": "number"
                },
                "vat": {
                  "type": "number",
                  "description": "Value from the VAT / Code column"
                },
                "grossValue": {
                  "type": "number"
                }
              }
            }
          }
        }
      }
    },
    "mostRecentShipment": {
      "type": "object",
      "required": [
        "shipmentNumber"
      ],
      "description": "Shipment with the most recent date (closest to today's date), always the last item in the list",
      "properties": {
        "sender": {
          "type": "object",
          "required": [
            "company"
          ],
          "properties": {
            "company": {
              "type": "string",
              "description": "Sender's company name as it appears"
            }
          }
        },
        "recipient": {
          "type": "object",
          "required": [
            "company"
          ],
          "properties": {
            "address": {
              "type": "string",
              "description": "Street address of the recipient as it appears, only including number and street"
            },
            "company": {
              "type": "string",
              "description": "Recipient's company name as it appears"
            },
            "zipCode": {
              "type": "string",
              "description": "Zip code of the recipient as it appears"
            }
          }
        },
        "weightInKg": {
          "type": "number",
          "description": "Weight of the shipment in kilograms"
        },
        "shipmentNumber": {
          "type": "string",
          "description": "Unique identifier for the shipment"
        },
        "referenceNumber": {
          "type": "string",
          "description": "Reference number for the shipment, must return null if not provided"
        },
        "additionalCharges": {
          "type": "array",
          "description": "Details of additional charges applied to the shipment",
          "items": {
            "type": "object",
            "required": [
              "description"
            ],
            "properties": {
              "grossValue": {
                "type": "number",
                "description": "Gross value of the charge, including VAT"
              },
              "description": {
                "type": "string",
                "description": "Description of the additional charge as it appears"
              }
            }
          }
        },
        "numberOfShipments": {
          "type": "number",
          "description": "Total number of shipments"
        }
      }
    }
  }
